entries[78124] = { ["name"] = "Magmastrahlen", ["text"] = "Sofort\nSchießt einen Strom kleiner Feuerstrahlen auf einen zufälligen Feind. Diese Strahlen verursachen 283 Feuerschaden bei allen Feinden im Umkreis von 3 Metern. Zusätzlich hinterlassen die Strahlen einen bleibenden Feuereffekt, der allen in der Nähe befindlichen Feinden 3 Feuerschaden zufügt." }
entries[78125] = { ["name"] = "Lodernder Schild", ["text"] = "150 Mana 40 Meter Reichweite\nWirken in 2 sek.\nGewährt dem Rüstungsschmied der Zwielichtdrachkin einen lodernden Schild. Angriffe auf das Ziel können eine Lohe auslösen. Heilt das Ziel 6 Sek. lang regelmäßig alle 2 Sek. um 1 Gesundheit.\n(2s Abklingzeit)" }
