entries[78144] = { ["name"] = "Sturmschlag", ["text"] = "8% von Grundmana Nahkampfreichweite\nSofort 8 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort mit beiden Waffen an. Zusätzlich werden die nächsten 4 Quellen des Naturschadens, der dem Ziel zugefügt wird, um 20% erhöht. Hält 12 Sek. lang an." }
entries[78145] = { ["name"] = "Erdschock", ["text"] = "18% von Grundmana 25 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 4 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 Sek. lang, dass diese Art Zauber gewirkt werden kann." }
