entries[78149] = { ["name"] = "Flammenzungenangriff", ["text"] = "Unbegrenzte Reichweite\nSofort\nErfüllt die Waffe des Schamanen mit Feuermagie, erhöht den gesamten Zauberschaden. Jeder Treffer fügt zusätzlichen Feuerschaden zu, abhängig vom Waffentempo. Langsamere Waffen verursachen mehr Feuerschaden pro Schwung. Hält 30 Minuten lang an." }
