entries[78151] = { ["name"] = "Heldentum", ["text"] = "26% von Grundmana\nSofort 5 min Abklingzeit\nErhöht Nahkampf-, Distanzangriffs- und Zaubertempo aller Gruppen- und Schlachtzugsmitglieder um 30%. Hält 40 Sek. lang an." }
